-- Diagnostics are printed before gates.
SELECT 'missing_retained_company' report,d.id,d.name FROM cleanup_dump d LEFT JOIN company c ON c.id=d.id WHERE c.id IS NULL;
SELECT 'missing_retained_customer_accounts' report,d.id,COUNT(ca.id) count FROM cleanup_dump d LEFT JOIN customer_account ca ON ca.company_id=d.id GROUP BY d.id HAVING COUNT(ca.id)=0;
SELECT 'company_unique_collision' report,GROUP_CONCAT(id ORDER BY id) company_ids,name,account_id,deleted FROM cleanup_company_projection p WHERE account_id IS NOT NULL GROUP BY name,account_id,deleted HAVING COUNT(*)>1;
SELECT 'user_portal_unique_collision' report,GROUP_CONCAT(p.id ORDER BY p.id) row_ids,COALESCE(m.final_id,p.company_id) final_company_id,p.username,p.is_deleted FROM user_portal p LEFT JOIN cleanup_company_map m ON m.old_id=p.company_id GROUP BY COALESCE(m.final_id,p.company_id),p.username,p.is_deleted HAVING COUNT(*)>1;
SELECT 'duplicate_name_suffix' report,id,old_name,new_name FROM cleanup_name_changes ORDER BY id;
-- All gates run before reference changes.
DELIMITER $$
BEGIN NOT ATOMIC
IF EXISTS (SELECT 1 FROM cleanup_dump d LEFT JOIN customer_account ca ON ca.company_id=d.id GROUP BY d.id HAVING COUNT(ca.id)=0) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Missing retained customer account'; END IF;
IF EXISTS (SELECT 1 FROM cleanup_dump d LEFT JOIN company c ON c.id=d.id WHERE c.id IS NULL) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Missing retained company'; END IF;
IF EXISTS (SELECT 1 FROM cleanup_company_map m JOIN cleanup_dump d ON d.id=m.old_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='A retained company is also a duplicate'; END IF;
IF EXISTS (SELECT 1 FROM cleanup_dump WHERE NULLIF(TRIM(`account_id`),'') IS NOT NULL AND (`account_id` NOT REGEXP '^[0-9]+$' OR CAST(`account_id` AS DECIMAL(65,0))>2147483647)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Invalid account_id; correct snapshot before cleanup'; END IF;
IF EXISTS (SELECT 1 FROM cleanup_dump WHERE NULLIF(TRIM(`bank_id`),'') IS NOT NULL AND (`bank_id` NOT REGEXP '^[0-9]+$' OR CAST(`bank_id` AS DECIMAL(65,0))>2147483647)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Invalid bank_id; correct snapshot before cleanup'; END IF;
IF EXISTS (SELECT 1 FROM cleanup_company_projection p WHERE account_id IS NOT NULL GROUP BY name,account_id,deleted HAVING COUNT(*)>1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Projected company unique-key collision'; END IF;
IF EXISTS (SELECT 1 FROM user_portal p LEFT JOIN cleanup_company_map m ON m.old_id=p.company_id GROUP BY COALESCE(m.final_id,p.company_id),p.username,p.is_deleted HAVING COUNT(*)>1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Projected user_portal unique-key collision'; END IF;
END$$
DELIMITER ;
